## Primitive deduplication

```js
const nums   = [1, 2, 2, 3, 3, 3];
const unique = [...new Set(nums)]; // [1, 2, 3]

const words   = ['apple', 'banana', 'apple', 'cherry'];
const uniqWords = [...new Set(words)]; // ['apple', 'banana', 'cherry']

// Order preserved, first occurrence wins:
const first = [...new Set([3, 1, 3, 2, 1])]; // [3, 1, 2]
```

## Why Set works

```js
const s = new Set();
s.add(1); s.add(1); s.add(2);
s.size;   // 2 — duplicates silently ignored
[...s];   // [1, 2]
```

## Object deduplication (by property)

```js
const users = [
  { id: 1, name: 'Alice' },
  { id: 2, name: 'Bob' },
  { id: 1, name: 'Alice (dup)' },
];

// Filter by first index match:
const unique = users.filter(
  (user, i, arr) => arr.findIndex(u => u.id === user.id) === i
);
// [ { id: 1, name: 'Alice' }, { id: 2, name: 'Bob' } ]

// Or Map-based (O(n) with Map lookup):
const byId = new Map(users.map(u => [u.id, u]));
const uniq = [...byId.values()];
```

## Named function declaration

```js
function greet(name) {
  return `Hello, ${name}`;
}
// Hoisted — callable before the line
// Name 'greet' appears in stack traces
```

## Named function expression

```js
const greet = function greetFn(name) {
  // greetFn is accessible inside the function for recursion
  return `Hello, ${name}`;
};
// greetFn is NOT accessible outside — only the variable greet is
```

## Anonymous function expression

```js
const greet = function(name) {
  return `Hello, ${name}`;
};
// Stack trace shows 'greet' (inferred from variable name) in modern engines
// but in some contexts shows 'anonymous'
```

## Stack trace comparison

```js
// Harder to debug:
setTimeout(function() { null.property; }, 0);
// TypeError: ... at anonymous

// Easier to debug:
setTimeout(function fetchData() { null.property; }, 0);
// TypeError: ... at fetchData
```

## Arrow functions are always anonymous

```js
const double = n => n * 2;
// 'double' is inferred from the variable name
// but you cannot refer to 'double' inside the function body
// (unlike a named function expression)
```

## Shim — adapts or normalises

A shim can change existing behaviour, not just add missing features:

```js
// Shim: normalise event listener API across old IE
if (window.attachEvent && !window.addEventListener) {
  window.addEventListener = function(type, fn) {
    this.attachEvent('on' + type, fn);
  };
}
// This maps the new API onto an old one — that's a shim
```

## Polyfill — implements a missing standard

```js
// Polyfill: add Promise to environments that don't have it
if (typeof Promise === 'undefined') {
  window.Promise = /* implementation matching the spec */;
}

// Polyfill: add Array.prototype.findLast (ES2023)
if (!Array.prototype.findLast) {
  Array.prototype.findLast = function(predicate) {
    for (let i = this.length - 1; i >= 0; i--) {
      if (predicate(this[i], i, this)) return this[i];
    }
  };
}
```

## Side-by-side comparison

| | Shim | Polyfill |
|---|---|---|
| Purpose | Adapt/normalise | Implement missing standard |
| Matches spec | Not necessarily | Yes, exactly |
| Scope | Any API | Future-standard API only |

Practically, the terms are often used interchangeably — 'polyfill' is just the more specific term.

## Basic IIFE

```js
(function () {
  const secret = 42;
  console.log(secret);
})();

console.log(typeof secret); // 'undefined' — not leaked
```

## Why the extra parentheses?

```js
// function keyword starts a DECLARATION here — can't call it immediately:
function() {}(); // SyntaxError

// Wrapping in () makes it an EXPRESSION:
(function() {})(); // ✅
// or:
(function() {}()); // ✅ — Crockford's style
// or:
!function() {}();  // ✅ — unary operator also works
+function() {}();
```

## Arrow function IIFE

```js
(() => {
  const private = 'scoped';
  console.log(private);
})();
```

## Async IIFE — still common today

```js
// In a CJS module or non-module script where top-level await isn't available:
(async () => {
  const data = await fetch('/api/config').then(r => r.json());
  init(data);
})();
```

## Modern alternative

ES modules give every file its own module scope — no IIFE needed for encapsulation. Block scope (`let`/`const`) handles the variable isolation case. But async IIFEs are still idiomatic.

## Default export

```js
// greet.js
export default function greet(name) {
  return `Hello, ${name}`;
}

// importer can name it anything:
import sayHello from './greet';
import hello    from './greet'; // same thing, different local name
```

## Named export

```js
// math.js
export const add      = (a, b) => a + b;
export const multiply = (a, b) => a * b;

// must use the exact exported name (or alias it):
import { add, multiply } from './math';
import { add as plus }  from './math'; // rename with 'as'
```

## Mixed

```js
// component.js
const Button = () => <button>Click</button>;
export const buttonStyles = { padding: '8px 16px' }; // named
export default Button;                                // default

// consumer:
import Button, { buttonStyles } from './component';
```

## Default export caveats

- Default exports are harder to tree-shake in some bundlers.
- Renaming at import site makes codebase-wide refactoring harder (no canonical name to search).
- React components use default exports by convention; utility functions generally use named exports.

## When to use

```js
class Timer {
  constructor() { this.ticks = 0; }

  start() {
    // ✅ Arrow preserves 'this' from the class instance
    setInterval(() => { this.ticks++; }, 1000);
  }
}

const nums = [1, 2, 3];
const doubled = nums.map(n => n * 2);       // ✅ short, clear
const odds    = nums.filter(n => n % 2);    // ✅
const total   = nums.reduce((a, n) => a+n); // ✅
```

## When NOT to use

```js
// ❌ Object method — 'this' is the outer scope, not the object
const counter = {
  count: 0,
  increment: () => { this.count++; }, // 'this' is NOT counter
};

// ✅ Use shorthand method syntax instead:
const counter = {
  count: 0,
  increment() { this.count++; },  // 'this' is counter
};

// ❌ Constructor:
const Person = (name) => { this.name = name; };
new Person('Aaron'); // TypeError: Person is not a constructor

// ❌ Generator:
const gen = *() => { yield 1; }; // SyntaxError — use function*

// ❌ When you need 'arguments':
const logArgs = () => console.log(arguments); // ReferenceError
```

## Spread — expand

```js
// Arrays
const a = [1, 2];
const b = [3, 4];
const merged = [...a, ...b];          // [1, 2, 3, 4]
const copy   = [...a];                // shallow clone

// Function call — replaces .apply()
Math.max(...[1, 3, 2]);               // 3
Math.max.apply(null, [1,3,2]);        // same (legacy)

// Objects (ES2018)
const user    = { name: 'Aaron' };
const updated = { ...user, role: 'dev' }; // shallow merge
```

## Rest — collect

```js
// Function parameters — collects remaining args:
function first(a, b, ...rest) {
  console.log(a);    // 1
  console.log(b);    // 2
  console.log(rest); // [3, 4, 5]
}
first(1, 2, 3, 4, 5);

// Array destructuring:
const [head, ...tail] = [1, 2, 3, 4]; // tail = [2,3,4]

// Object destructuring:
const { id, ...attrs } = { id: 1, name: 'A', age: 30 };
// attrs = { name: 'A', age: 30 }
```

## Key difference

```
Spread: [1,2] → 1, 2   (array to elements — expands)
Rest:   1, 2  → [1,2]  (elements to array — collects)
```

## Object destructuring

```js
const user = { name: 'Aaron', age: 30, role: 'dev' };

// Basic:
const { name, role } = user;

// Rename:
const { name: userName, role: userRole } = user;

// Default value:
const { name, level = 1 } = user; // level is 1 if not in user

// Nested:
const { address: { city } } = { address: { city: 'London' } };

// Function parameter:
function greet({ name, greeting = 'Hi' }) {
  return `${greeting}, ${name}`;
}
greet({ name: 'Aaron' }); // 'Hi, Aaron'
```

## Array destructuring

```js
const [a, b, c] = [1, 2, 3];

// Skip elements:
const [first, , third] = [10, 20, 30]; // third = 30

// Rest:
const [head, ...tail] = [1, 2, 3, 4];  // tail = [2,3,4]

// Swap values:
let x = 1, y = 2;
[x, y] = [y, x]; // x=2, y=1

// From function return:
const [data, error] = await fetchData();
```

## In for...of

```js
const map = new Map([['a', 1], ['b', 2]]);
for (const [key, value] of map) {
  console.log(key, value);
}
```
